import fs from 'node:fs';
import path from 'node:path';
import matter from 'gray-matter';
import type { Posts } from '../types/entry.interface';
import { isPostDate, isPostPath } from '../types/primitives';

const POST_DIRECTORY_PATTERN = /^\d{4}$/;
const POST_FILENAMES = ['index.md', 'index.mdx'] as const;

const readAiGeneratedFlag = (value: unknown): boolean => {
  // Missing metadata keeps existing posts backward-compatible. A quoted
  // string is intentionally not treated as true so a typo cannot disclose an
  // article as AI-generated by accident.
  return value === true;
};

/** Fails the build with the offending file rather than propagating a malformed value. */
const toPost = (data: Record<string, unknown>, filepath: string): Posts => {
  const { path: postPath, date } = data;
  if (typeof postPath !== 'string' || !isPostPath(postPath)) {
    throw new Error(`Invalid or missing "path" front matter in ${filepath}: ${String(postPath)}`);
  }
  if (typeof date !== 'string' || !isPostDate(date)) {
    throw new Error(`Invalid or missing "date" front matter in ${filepath}: ${String(date)}`);
  }
  return {
    ...(data as Omit<Posts, 'path' | 'date' | 'aiGenerated' | 'filepath'>),
    path: postPath,
    date,
    aiGenerated: readAiGeneratedFlag(data.aiGenerated),
    filepath,
  };
};

const listPostFiles = (directory: string): string[] =>
  fs
    .readdirSync(directory, { withFileTypes: true })
    .filter((entry) => entry.isDirectory() && POST_DIRECTORY_PATTERN.test(entry.name))
    .sort((left, right) => left.name.localeCompare(right.name))
    .flatMap((entry) => {
      const postDirectory = path.join(/* turbopackIgnore: true */ directory, entry.name);
      const postFiles = POST_FILENAMES.map((filename) =>
        path.join(/* turbopackIgnore: true */ postDirectory, filename),
      ).filter(fs.existsSync);

      if (postFiles.length > 1) {
        throw new Error(`Multiple post documents found in ${postDirectory}`);
      }
      return postFiles;
    });

export class PostFileRepository {
  public constructor(private readonly directory: string) {}

  public findAll(limit?: number): Posts[] {
    const postFiles = listPostFiles(this.directory);
    let filesToRead = postFiles;
    if (limit !== undefined) {
      const sampleSize = Math.max(0, Math.floor(limit));
      filesToRead = postFiles.slice(Math.max(0, postFiles.length - sampleSize));
    }

    return filesToRead.map((filepath) => {
      const fileContents = fs.readFileSync(filepath, 'utf8');
      const { data } = matter(fileContents);
      return toPost(data, filepath);
    });
  }
}
